parameters.jsCode:
const items = $input.all();

const requiredFields = [
  "Date",
  "Expense_ID",
  "Department",
  "Category",
  "Description",
  "Amount",
  "Payment_Method",
  "Vendor"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const amount = Number(data.Amount);

  if (
    missingFields.length === 0 &&
    !isNaN(amount) &&
    amount >= 0
  ) {

    validItems.push({
      ...data,
      Amount: amount
    });

  } else {

    invalidItems.push({
      expense_id: data.Expense_ID || "Unknown",
      missing_fields: missingFields
    });

  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_records: items.length,
      valid_records: validItems.length,
      invalid_records: invalidItems.length,
      invalid_details: invalidItems,
      expense_data: validItems
    }
  }
];

const data = $json.expense_data;

if (data.length === 0) {
  throw new Error("No expense records found.");
}

const totalExpense = data.reduce(
  (sum, item) => sum + Number(item.Amount),
  0
);

const averageExpense =
  totalExpense / data.length;

const highestExpense =
  Math.max(...data.map(item => Number(item.Amount)));

const highestExpenseRecord =
  data.find(
    item => Number(item.Amount) === highestExpense
  );

const categoryTotals = {};

for (const item of data) {

  const category = item.Category;
  const amount = Number(item.Amount);

  if (!categoryTotals[category]) {
    categoryTotals[category] = 0;
  }

  categoryTotals[category] += amount;
}

const categoryAnalysis = Object.entries(categoryTotals)
  .map(([category, amount]) => ({
    category,
    total_expense: Number(amount.toFixed(2)),
    percentage_of_total: Number(
      ((amount / totalExpense) * 100).toFixed(2)
    )
  }))
  .sort(
    (a, b) => b.total_expense - a.total_expense
  );

return [
  {
    json: {
      expense_data: data,

      total_expense:
        Number(totalExpense.toFixed(2)),

      average_expense:
        Number(averageExpense.toFixed(2)),

      highest_expense:
        highestExpense,

      highest_category:
        highestExpenseRecord.Category,

      highest_expense_description:
        highestExpenseRecord.Description,

      category_analysis:
        categoryAnalysis
    }
  }
];

const data = $json.expense_data;

const averageExpense =
  Number($json.average_expense);

const highExpenseThreshold =
  averageExpense * 2;

const highExpenses = data.filter(
  item =>
    Number(item.Amount) > highExpenseThreshold
);

return [
  {
    json: {
      ...$json,

      high_expense_threshold:
        Number(highExpenseThreshold.toFixed(2)),

      high_expense_count:
        highExpenses.length,

      high_expenses:
        highExpenses
    }
  }
];

